/* crosswalk cards, r30. */
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30a"]=[{"q": "The least total length of countably many open intervals covering a set A. What is it called?", "a": "the outer size of A", "w": ["the size of A", "the length of A", "the cover of A"], "why": "Outer size is the greatest lower bound of the totals of all covers."}, {"q": "What is the outer size of [2, 5]?", "a": "3", "w": ["5", "2", "0"], "why": "Cover-total: the outer size of an interval is its length."}, {"q": "What is the outer size of the fractions in [0, 1]?", "a": "0", "w": ["1", "1/2", "endless"], "why": "Countably many points; outer-adds-at-most gives 0 + 0 + ⋯ = 0."}, {"q": "A line reads m*(A₁ ∪ A₂ ∪ ⋯) ≤ m*(A₁) + m*(A₂) + ⋯. Which technique licenses it?", "a": "outer-adds-at-most", "w": ["cover-total", "shift-keeps", "no-size-set"], "why": "The covers of the pieces together cover the union, with ε/2ⁿ of slack each."}, {"q": "A is any set of reals. A line reads m*(A + 7) = m*(A). Which technique licenses it?", "a": "shift-keeps", "w": ["cover-total", "outer-adds-at-most", "no-size-set"], "why": "Sliding every interval of a cover by 7 keeps its length."}, {"q": "Are √2 and √2 + 1/3 kin?", "a": "yes: their difference is a fraction", "w": ["no: both are irrational", "no: kin must both be fractions", "yes: both lie in [1, 2]"], "why": "Kin means x − y is a fraction, and −1/3 is one."}, {"q": "Are √2/2 and √2/4 kin?", "a": "no: their difference is not a fraction", "w": ["yes: one is half the other", "yes: both are irrational", "no: they lie in different halves"], "why": "The difference √2/4 is not a fraction."}, {"q": "Which line of the no-size-set proof needs choice?", "a": "picking V, one real from each box", "w": ["listing the fractions in [−1, 1]", "sliding V by each qᵢ", "adding the sizes of the copies"], "why": "There are more boxes than any list, and no technique to pick by (6b)."}, {"q": "If V had a size, 1 ≤ m(V) + m(V) + ⋯ ≤ 3. What breaks?", "a": "no number m(V) fits", "w": ["m(V) must be 1/3", "m(V) must be 1", "m(V) must be 3"], "why": "Zero gives a sum of 0; anything positive gives an endless sum."}, {"q": "A set has outer size 0. Is it empty?", "a": "not necessarily", "w": ["yes, always", "only if it is closed", "yes, if it is countable"], "why": "A single point, or all the fractions, has outer size 0."}, {"q": "A claim: “outer size adds over any two separate sets.” Is it allowed?", "a": "no: V’s slid copies refute it", "w": ["yes: cover-total gives it", "yes: shift-keeps gives it", "no: only for intervals of length 0"], "why": "If outer size added, n · m*(V) ≤ 3 for every n, so m*(V) = 0, and the copies could not cover [0, 1]."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30b"]=[{"q": "m*(E) = m*(E ∩ A) + m*(E ∖ A) for every set E. What is A called?", "a": "sized", "w": ["outer", "countable", "separate"], "why": "The split test: A cuts every set’s outer size exactly."}, {"q": "To check the split test, which way of the inequality needs work?", "a": "m*(E ∩ A) + m*(E ∖ A) ≤ m*(E)", "w": ["m*(E) ≤ m*(E ∩ A) + m*(E ∖ A)", "m*(E ∩ A) ≤ m*(E)", "m*(E ∖ A) ≤ m*(E)"], "why": "The other way always holds, by outer-adds-at-most."}, {"q": "A is sized. Is the set of reals outside A sized?", "a": "yes, always", "w": ["only if A is an interval", "only if A has size 0", "not necessarily"], "why": "The split test cuts E into the same two pieces, swapped."}, {"q": "A₁, A₂, A₃, … are sized. Is their union sized?", "a": "yes", "w": ["only if they are separate", "only if finitely many", "only if they are intervals"], "why": "The sized-family technique: countable unions of sized sets are sized."}, {"q": "A line reads m(A₁ ∪ A₂ ∪ ⋯) = m(A₁) + m(A₂) + ⋯ for separate sized sets. Which technique licenses it?", "a": "countable-adding", "w": ["outer-adds-at-most", "split-test", "shift-keeps"], "why": "Countable adding gives equality; outer-adds-at-most gives only ≤."}, {"q": "What is m([0, 2] ∪ [1, 3])?", "a": "3", "w": ["4", "2", "5"], "why": "The union is [0, 3]; adding 2 + 2 counts [1, 2] twice."}, {"q": "Is the set of fractions in [0, 1] sized?", "a": "yes, with size 0", "w": ["no, it is not an interval", "yes, with size 1", "no, it is in every interval"], "why": "Outer size 0 passes the split test."}, {"q": "What is the size of the numbers in [0, 1) whose first decimal digit is 3 or 7?", "a": "0.2", "w": ["0.02", "0.8", "2"], "why": "[0.3, 0.4) and [0.7, 0.8), each of size 0.1."}, {"q": "Every set of reals is a union of single points, and points are sized. Why is every set not sized?", "a": "most sets have more points than any list", "w": ["points have size 0", "points are not intervals", "unions of sized sets are never sized"], "why": "The sized-family technique joins only countably many."}, {"q": "Accepted name for a sized set?", "a": "measurable set", "w": ["outer measure", "open set", "countable set"], "why": "Sized is the plain name; measurable is the accepted one."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30c"]=[{"q": "s = 3 on [0, 2), 1 on [2, 5], 0 elsewhere. What is ∫ s dm?", "a": "9", "w": ["4", "6", "11"], "why": "Value times size: 3 · 2 + 1 · 3."}, {"q": "A function takes finitely many values, each on a sized set. What is it called?", "a": "a step function", "w": ["a sized function", "a continuous function", "a fenced function"], "why": "A step function; its total is the sum of value times size."}, {"q": "{f > t} is sized for every t. What is f called?", "a": "sized", "w": ["a step function", "continuous", "integrable"], "why": "A sized function has every height set sized."}, {"q": "Is a continuous function sized?", "a": "yes", "w": ["only if it has a ceiling", "only on a closed interval", "no"], "why": "{f > t} is open, and open sets are sized."}, {"q": "Is 10d’s q, 1 at fractions and 0 elsewhere, sized?", "a": "yes, its total is 0", "w": ["no, it has no area", "yes, its total is 1", "no, it jumps everywhere"], "why": "Its height sets are empty, the fractions, or the line."}, {"q": "The total of a sized f ≥ 0 is the least upper bound of what?", "a": "totals of step functions below f", "w": ["lower sums of f", "upper sums of f", "totals of step functions above f"], "why": "The total is the best that can be done from below."}, {"q": "A line reads sₙ = min(n, ⌊2ⁿf⌋/2ⁿ), and sₙ rises to f. Which technique is this?", "a": "total-from-below", "w": ["step-total", "height-slices", "agrees-with-area"], "why": "Round the heights down to a multiple of 1/2ⁿ, capped at n."}, {"q": "f ≥ 0 continuous on [u, v]. A line reads ∫ f dm over [u, v] = ∫ₐᵇ f(x) dx. Which technique licenses it?", "a": "agrees-with-area", "w": ["total-from-below", "step-total", "height-slices"], "why": "The total lies between every lower and upper sum, so exactly-one-between gives the area."}, {"q": "f = 0 except at x = 3, where f = 1. What is ∫ f dm?", "a": "0", "w": ["1", "3", "it has no total"], "why": "f differs from 0 on a size-0 set, and the total cannot see it."}, {"q": "A claim: “∫ f dm = 0, so f = 0 at every point.” What is true?", "a": "f = 0 except on a size-0 set", "w": ["f = 0 at every point", "f = 0 on an interval", "f has no total"], "why": "A total cannot see a size-0 set."}, {"q": "∫f and ∫g are both ∞. Is ∫(f − g) = ∫f − ∫g allowed?", "a": "no: ∞ − ∞ has no value", "w": ["yes: both are ∞", "yes: it gives 0", "no: f − g is never sized"], "why": "Split a total into two only when ∫|f| is finite."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30d"]=[{"q": "0 ≤ f₁ ≤ f₂ ≤ ⋯ settle at f at every x. What follows?", "a": "∫fₙ settles at ∫f", "w": ["∫f ≤ the lower limit of ∫fₙ only", "nothing without a fence", "∫fₙ is the same for every n"], "why": "The rising-limit technique."}, {"q": "A line reads ∫ (lower limit of fₙ) ≤ lower limit of ∫fₙ, for fₙ ≥ 0. Which technique licenses it?", "a": "lower-limit", "w": ["rising-limit", "fenced-limit", "step-total"], "why": "The lower-limit technique gives only ≤."}, {"q": "|fₙ| ≤ g for every n, ∫g finite, and fₙ settles at f at every x. Which technique passes the limit through?", "a": "fenced-limit", "w": ["rising-limit", "lower-limit", "total-from-below"], "why": "One fence with a finite total locks the totals in place."}, {"q": "fₙ = 1 on [n, n + 1], 0 elsewhere. What are lim ∫fₙ and ∫ lim fₙ?", "a": "1 and 0", "w": ["0 and 0", "1 and 1", "0 and 1"], "why": "The bump slides off to the right and takes its total with it."}, {"q": "fₙ = n on (0, 1/n], 0 elsewhere. What is ∫fₙ?", "a": "1 for every n", "w": ["1/n", "n", "0"], "why": "n times a size of 1/n."}, {"q": "The vₙ are the greatest lower bounds of uₙ, uₙ₊₁, …. What is the number they rise to called?", "a": "the lower limit", "w": ["the least upper bound", "the limit", "the fence"], "why": "The lowest value the list keeps coming back near."}, {"q": "fₙ(x) = xⁿ on [0, 1]. Which fence works?", "a": "g = 1 on [0, 1]", "w": ["g = x on [0, 1]", "g = 1 everywhere", "no fence works"], "why": "xⁿ ≤ 1 on [0, 1], and that g has total 1."}, {"q": "g = 1 everywhere stands over the sliding bump. Why is it no fence?", "a": "its total is endless", "w": ["it is not sized", "it is not a step function", "it is not above the bump"], "why": "The fenced-limit proof takes away ∫g, which must be finite."}, {"q": "fₙ = 1/n on [0, n]. It settles to 0 everywhere at once. What are the totals?", "a": "1 for every n", "w": ["1/n", "0", "n"], "why": "Settling everywhere at once on an endless line does not carry the totals."}, {"q": "Does fenced-limit need the list to settle everywhere at once?", "a": "no, point by point is enough", "w": ["yes, as in 23e", "yes, and to rise", "only on [0, 1]"], "why": "The fence takes away the room to escape; the pace does not matter."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30e"]=[{"q": "What is the size of the rectangle [0, 2] × [1, 4] in the plane?", "a": "6", "w": ["5", "8", "3"], "why": "Product size: m([0, 2]) · m([1, 4]) = 2 · 3."}, {"q": "Eₓ is the set of y with (x, y) in E. What is it called?", "a": "the slice of E at x", "w": ["the height set of E", "the cover of E", "the shadow of E"], "why": "A slice at x, one for each place along the bottom edge."}, {"q": "A line reads m₂(E) = ∫ m(Eₓ) dx for a sized set E. Which technique licenses it?", "a": "slices", "w": ["cover-total", "countable-adding", "rising-limit"], "why": "The slices technique: size is the total of the slices’ lengths."}, {"q": "The triangle under y = x on [0, 2]: what is the length of its slice at x = 1.5?", "a": "1.5", "w": ["0.5", "2", "0.75"], "why": "The slice is [0, x]."}, {"q": "f ≥ 0 is sized on the plane. A line swaps ∫(∫ f dy) dx for ∫(∫ f dx) dy. Which technique licenses it?", "a": "either-order-sized", "w": ["slices", "fenced-limit", "agrees-with-area"], "why": "For f ≥ 0, either order gives the same total."}, {"q": "f takes both signs. What makes either order safe?", "a": "the total of |f| is finite", "w": ["both orders are finite", "f is continuous on each square", "f has no jumps"], "why": "Split f = f⁺ − f⁻; each part then has a finite total."}, {"q": "The staircase of squares: one order gives 0, the other 1. Why does the technique not apply?", "a": "the total of |f| is endless", "w": ["f is not sized", "f has jumps", "f takes only two values"], "why": "Endlessly many unit squares make ∫∫|f| endless."}, {"q": "Is a line segment in the plane sized, and what size?", "a": "yes, size 0", "w": ["yes, its length", "no", "yes, size 1"], "why": "A thin rectangle of size as small as you like covers it."}, {"q": "A sized set in the plane. Is every one of its slices sized?", "a": "except on a size-0 set of x", "w": ["yes, every one", "only if it is a rectangle", "no slice need be"], "why": "{0} × V has size 0, yet its slice at 0 is V."}, {"q": "Accepted name for the product sizes on the plane?", "a": "product measure", "w": ["outer measure", "double integral", "σ-algebra"], "why": "The plain name is product size."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30f"]=[{"q": "A set Ω, a family of events, and a size P with P(Ω) = 1. What is this called?", "a": "a chance space", "w": ["a sized family", "a step function", "a given chance"], "why": "Chance is size, with the whole of size one."}, {"q": "P(A) = 0.3. What is P(not A)?", "a": "0.7", "w": ["0.3", "0.09", "1.3"], "why": "Chance: P(not A) = 1 − P(A)."}, {"q": "A line reads P(A ∪ B) = P(A) + P(B) − P(A ∩ B). Which technique licenses it?", "a": "chance", "w": ["whole-chance", "turn-around", "given-chance"], "why": "Split A ∪ B into A and B ∖ A; size adds."}, {"q": "P(A ∩ B) / P(B), for P(B) > 0. What is it?", "a": "the chance of A given B", "w": ["the chance of B given A", "the chance of A or B", "the chance of A and B"], "why": "B becomes the whole, and A is measured inside it."}, {"q": "P(A ∩ B) = P(A) P(B). What are A and B called?", "a": "independent", "w": ["separate", "sized", "given"], "why": "Knowing B tells nothing about A."}, {"q": "A line reads P(A) = P(A | B₁)P(B₁) + P(A | B₂)P(B₂), with B₁, B₂ separate and filling Ω. Which technique licenses it?", "a": "whole-chance", "w": ["turn-around", "chance", "independent"], "why": "A splits into A ∩ B₁ and A ∩ B₂."}, {"q": "A line reads P(B | A) = P(A | B) P(B) / P(A). Which technique licenses it?", "a": "turn-around", "w": ["whole-chance", "given-chance", "chance"], "why": "P(A ∩ B) written two ways."}, {"q": "Two fair dice. What is the chance of a total of 7?", "a": "1/6", "w": ["7/36", "1/12", "1/11"], "why": "Six of the 36 outcomes."}, {"q": "A test catches 99 in 100 who have a rare condition. Is P(has it | +) about 0.99?", "a": "no, it depends on how rare it is", "w": ["yes, always", "yes, if false alarms are few", "no, it is 0.01"], "why": "Turning it around needs P(has it)."}, {"q": "A and B are separate, each with chance 1/6. Are they independent?", "a": "no", "w": ["yes", "only if P(A ∪ B) = 1/3", "yes, since they share no point"], "why": "P(A ∩ B) = 0, but P(A)P(B) = 1/36."}, {"q": "A dart thrown with no aim within [0, 1] lands at 0.5. What chance did that point have?", "a": "0", "w": ["1/2", "1", "none at all"], "why": "Each single point has size 0, yet the dart lands somewhere."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30g"]=[{"q": "What is a chance variable?", "a": "a sized function on a chance space", "w": ["a number that changes in time", "an event of chance 1/2", "the chance of an event"], "why": "Each outcome gets a number, and every set {X &gt; t} is an event."}, {"q": "What is the average E X of a chance variable?", "a": "its total ∫ X dP over the chance space", "w": ["its middle value", "its most likely value", "its largest value over 2"], "why": "Chance plays the part of size; the step-total gives 5·stat’s weighted average."}, {"q": "One fair die. What is its average?", "a": "3.5", "w": ["3", "4", "6"], "why": "(1 + ⋯ + 6)/6. No face shows 3.5: an average need not be a value."}, {"q": "The total of two dice, which need not be independent. What licenses E(X + Y) = 7?", "a": "the average-adds technique", "w": ["the independent-averages-multiply technique", "the independent-spreads-add technique", "the spread-of-a-sum technique"], "why": "Averages add with no condition at all; the other techniques ask for more or speak of spreads."}, {"q": "What is Var X, the spread?", "a": "E(X − μ)², the averaged squared stray", "w": ["E|X| − μ", "the largest value minus the least", "E X − μ²"], "why": "Its root is the spread width; short way E X² − μ²."}, {"q": "Var(aX + b) is what?", "a": "a² Var X", "w": ["a Var X + b", "a² Var X + b²", "a Var X"], "why": "A shift does not spread; a stretch by a squares the spread."}, {"q": "A one-or-zero chance variable with chance p of 1. What is its spread?", "a": "p(1 − p)", "w": ["p", "p²", "1 − p"], "why": "E X² = E X = p, so Var X = p − p²; largest, 1/4, at p = 1/2."}, {"q": "X and Y independent. What licenses Var(X + Y) = Var X + Var Y?", "a": "the independent-spreads-add technique", "w": ["the average-adds technique", "the spread-bound technique", "the chance technique"], "why": "Independent gives Cov(X, Y) = 0 through E(XY) = E X E Y; average-adds alone leaves the co-spread term."}, {"q": "Two independent errors, widths 3 g and 4 g. What is the width of their sum?", "a": "5 g", "w": ["7 g", "12 g", "1 g"], "why": "Spreads add: 9 + 16 = 25. Widths combine like the sides of a right triangle."}, {"q": "Cov(X, Y) = 0. What follows?", "a": "Var(X + Y) = Var X + Var Y, but not that X and Y are independent", "w": ["X and Y are independent", "X = Y", "E X = E Y = 0"], "why": "X = −1, 0, 1 and Y = X² have co-spread 0, yet Y is fixed by X."}, {"q": "The average of n independent copies, each of spread σ². What is its spread width?", "a": "σ/√n", "w": ["σ/n", "σ", "nσ"], "why": "Spread nσ²/n² = σ²/n."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30h"]=[{"q": "X ≥ 0 with average 20. What is the most P(X ≥ 100) can be?", "a": "1/5", "w": ["1/100", "1/20", "4/5"], "why": "Stray-bound: E X / a = 20/100."}, {"q": "Which technique bounds P(X ≥ a) using only the average of X ≥ 0?", "a": "the stray-bound technique", "w": ["the spread-bound technique", "the averages-settle technique", "the finitely-often technique"], "why": "a·1{X ≥ a} ≤ X, then average both sides."}, {"q": "At most what share of any chance pattern’s chance lies three widths or more from its average?", "a": "1/9", "w": ["1/3", "0.27 percent", "1/27"], "why": "Spread-bound 1/k² with k = 3. The bell does far better, but the bound holds for every chance pattern."}, {"q": "Why does the stray-bound need X ≥ 0?", "a": "a·1{X ≥ a} ≤ X fails where X is negative", "w": ["E X must be positive to divide", "negative chances are not allowed", "a must be a whole number"], "why": "W = ±1 has average 0, yet P(W ≥ 1) = 1/2."}, {"q": "n independent copies with spread σ². What bounds P(|X̄ₙ − μ| ≥ ε)?", "a": "σ²/(nε²)", "w": ["σ/(nε)", "σ²/ε²", "1/n²"], "why": "Spread-bound on X̄ₙ, whose spread is σ²/n."}, {"q": "A poll of 1000 voters. At most how wide is the share’s spread width?", "a": "about 0.016", "w": ["0.5", "0.001", "0.05"], "why": "σ ≤ 1/2, so 0.5/√1000 ≈ 0.016."}, {"q": "To halve the width of a poll, how many more voters?", "a": "four times as many", "w": ["twice as many", "half as many", "eight times as many"], "why": "The width is σ/√n."}, {"q": "Σ P(Aₙ) is finite. What licenses ‘only finitely many Aₙ happen, with chance 1’?", "a": "the finitely-often technique", "w": ["the averages-settle technique", "the independent technique", "the whole-chance technique"], "why": "The tails of a settling sum head to 0; no independence is needed."}, {"q": "Five tails in a row on a fair coin. What is the chance of a head next?", "a": "1/2", "w": ["more than 1/2", "1/64", "less than 1/2"], "why": "Independent tosses: the coin is never due."}, {"q": "As tosses grow, what happens to the number of heads minus n/2?", "a": "its width √n/2 grows", "w": ["it shrinks to 0", "it stays at 0", "it settles at 1/2"], "why": "The share settles because the difference is divided by n."}, {"q": "What does the surely-settle technique add to averages-settle?", "a": "with chance 1 the averages settle and the strays stop for good", "w": ["the strays are rare at each large n", "the average equals μ after finitely many tries", "no spread is needed at all"], "why": "The fourth-average bound adds up to a finite total, so finitely-often applies."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30i"]=[{"q": "What is the chance function of a whole-number chance variable X?", "a": "G(s) = E sˣ = Σ pₖ sᵏ", "w": ["G(s) = P(X ≤ s)", "G(s) = E eˢˣ", "G(s) = Σ k pₖ"], "why": "The storing function of the list of chances (23j)."}, {"q": "How is P(X = k) read back from G?", "a": "G⁽ᵏ⁾(0)/k!", "w": ["G(k)", "G′(k)", "G(1)/k"], "why": "Chances-from-G: 23j’s read-back."}, {"q": "What is G(1) for every chance function?", "a": "1", "w": ["the average", "0", "the spread"], "why": "The chances add to 1."}, {"q": "Where is the average in G?", "a": "G′(1), the slope at 1", "w": ["G(1)", "G(0)", "G″(1)"], "why": "Average-from-G, by the rising limit as s rises to 1."}, {"q": "One coin with chance p of heads. What is its chance function?", "a": "1 − p + ps", "w": ["p + s", "ps", "(1 − p)s"], "why": "Chance 1 − p of 0, chance p of 1."}, {"q": "X, Y independent counts. What licenses G<sub>X+Y</sub> = G<sub>X</sub> G<sub>Y</sub>?", "a": "the sums-multiply technique", "w": ["the average-adds technique", "the chances-from-G technique", "the whole-chance technique"], "why": "sˣ⁺ʸ = sˣsʸ, then independent averages multiply."}, {"q": "A rare count with average λ. What is its chance function?", "a": "e^(λ(s − 1))", "w": ["λs", "e^(λs)", "(1 + s)^λ"], "why": "Σ e^(−λ)λᵏsᵏ/k!, the growth sum."}, {"q": "Two independent rare counts, averages 2 and 3. What is their total?", "a": "a rare count with average 5", "w": ["a rare count with average 6", "not a rare count", "a rare count with average √13"], "why": "e^(2(s − 1))e^(3(s − 1)) = e^(5(s − 1))."}, {"q": "Each member of a family line has children by G. What is the chance the line dies out?", "a": "the least s in [0, 1] with G(s) = s", "w": ["G(0)", "1 − G′(1)", "always 1, since G(1) = 1"], "why": "Dying-out: qₙ = G(qₙ₋₁) climbs from 0 to the first meeting with the line."}, {"q": "Each member has 0, 1 or 2 children with chances 1/4, 1/4, 1/2. What is the dying-out chance?", "a": "1/2", "w": ["1", "1/4", "0"], "why": "2s² − 3s + 1 = 0 has roots 1/2 and 1."}, {"q": "The average number of children is exactly 1, and not every member has one child. What happens?", "a": "the line dies out with chance 1", "w": ["it goes on for ever", "it dies out with chance 1/2", "it grows without end"], "why": "The curve G stays above the line until s = 1."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30j"]=[{"q": "What is ∫ e^(−x²) dx over the whole line?", "a": "√π", "w": ["π", "1", "√(2π)"], "why": "Bell-total: square it, turn to r and θ, and get π."}, {"q": "How does the bell-total proof find I?", "a": "it finds I² as a total over the plane in r and θ", "w": ["it undoes the slope of e^(−x²)", "it adds a power sum term by term", "it uses the spread-bound"], "why": "No formula undoes the slope; the plane gives the whole-line total only."}, {"q": "What is the bell’s density φ(x)?", "a": "e^(−x²/2)/√(2π)", "w": ["e^(−x²)", "e^(−x²/2)", "e^(−x)/2"], "why": "Total 1 from the bell-total with x = √2 u."}, {"q": "What are the bell’s average and spread?", "a": "0 and 1", "w": ["1 and 0", "0 and √(2π)", "1/2 and 1/2"], "why": "φ is the same on both sides of 0, and ∫ x²φ = 1."}, {"q": "What is the average-function M(t)?", "a": "E e^(tX)", "w": ["E sˣ", "E tX", "E X^t"], "why": "It works for any chance variable, not only counts."}, {"q": "What is the bell’s own average-function?", "a": "e^(t²/2)", "w": ["e^(−t²/2)", "1 + t", "e^t"], "why": "Complete the square in tx − x²/2."}, {"q": "X, Y independent. What licenses M<sub>X+Y</sub> = M<sub>X</sub> M<sub>Y</sub>?", "a": "the average-function technique", "w": ["the bell-total technique", "the average-adds technique", "the spread-of-a-sum technique"], "why": "e^(t(X+Y)) = e^(tX)e^(tY), then independent averages multiply."}, {"q": "Zₙ = (Sₙ − nμ)/(σ√n). What does the central limit technique give?", "a": "P(a &lt; Zₙ ≤ b) heads to the bell’s chance from a to b", "w": ["Sₙ heads to the bell", "each Xₖ is close to a bell", "Zₙ settles at 0"], "why": "Only the rescaled sum heads to the bell."}, {"q": "Which step of the central limit proof is held in trust?", "a": "matching average-functions give matching limits of chances", "w": ["the bell-total", "(1 + xₙ/n)ⁿ heads to eˣ", "sums multiply"], "why": "Its proof waits much higher up the ladder."}, {"q": "P(−2 &lt; Z ≤ 2) ≈ 0.9545. How does that compare with the spread-bound?", "a": "the bell leaves 0.0455 outside, the bound allows 1/4", "w": ["they are equal", "the bound is smaller", "the bell leaves 1/4 outside"], "why": "The bound holds for every chance pattern, so it is cautious."}, {"q": "100 fair dice. What is the spread width of their total?", "a": "about 17.1", "w": ["35/12", "291.7", "10"], "why": "√(100 × 35/12)."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30k"]=[{"q": "What makes a game fair here?", "a": "given any history, the next fortune averages the present one", "w": ["every round is won half the time", "the fortune never changes", "the stakes are equal"], "why": "E(Xₙ₊₁ | h) = Xₙ on h."}, {"q": "In a fair game, E Xₙ = E X₀. Which technique?", "a": "the fair-stays-fair technique", "w": ["the ruin-chance technique", "the average-adds technique", "the dying-out technique"], "why": "Whole-chance over histories, then induction on n."}, {"q": "What is a stopping technique?", "a": "a round chosen by looking only at the past", "w": ["a round chosen after the game ends", "the round before the biggest loss", "the last round of the game"], "why": "Whether T = n is decided by the history up to round n."}, {"q": "Is ‘stop the round before a loss’ a stopping technique?", "a": "no: it looks ahead", "w": ["yes, if the game is fair", "yes, if it stops in time", "no: it never stops"], "why": "With it, E X_T = 7/8 in three rounds: looking ahead beats the game."}, {"q": "T is a bounded stopping technique in a fair game. What licenses E X<sub>T</sub> = E X₀?", "a": "the stopping-keeps technique", "w": ["the fair-stays-fair technique", "the fenced-limit technique", "the ruin-chance technique"], "why": "Each step before stopping averages 0, over finitely many rounds."}, {"q": "Stop the first time you are 1 ahead, with no cap. Why does stopping-keeps fail?", "a": "T has no bound", "w": ["the game is not fair", "T looks ahead", "the stakes change"], "why": "X_T = 1 always, yet X₀ = 0."}, {"q": "Doubling after each loss on a fair coin, stakes up to 512. What are the average winnings?", "a": "0", "w": ["1", "1023/1024", "−1"], "why": "Win 1 with chance 1023/1024, lose 1023 with chance 1/1024."}, {"q": "What does doubling need in order to win surely, and why is it ruled out?", "a": "stakes with no ceiling and a stopping time with no bound", "w": ["a biased coin", "a fair coin and a fixed stake", "only a large bankroll"], "why": "The no-system technique asks for both bounds."}, {"q": "Start with 10, target 50, one dollar a round on a fair coin. What is the chance of reaching 50?", "a": "1/5", "w": ["1/2", "4/5", "1/50"], "why": "Ruin-chance: k/N."}, {"q": "Start with 90, target 100, fair coin. What happens?", "a": "win 10 with chance 9/10, lose 90 with chance 1/10, average gain 0", "w": ["win surely", "average gain 9", "lose with chance 9/10"], "why": "Ruin-chance k/N = 9/10."}, {"q": "A fair walk of 100 rounds from 0. What is its spread width?", "a": "10", "w": ["0", "100", "50"], "why": "Only the average is kept; the walk spreads like √n."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30l"]=[{"q": "Ω has n equally likely outcomes, and A is made of k of them. P(A) is:", "a": "k/n", "w": ["1/k", "k/(n − k)", "n/k"], "why": "The equal-cases technique (30l1)."}, {"q": "Which licenses 1 = P({ω₁}) + ⋯ + P({ωₙ}) in the proof of the equal-cases technique?", "a": "The countable-adding technique (30b3), with P(Ω) = 1", "w": ["The turn-around technique (30f3)", "The independent technique (30f2)", "The at-least-one technique (30l2)"], "why": "The one-outcome events are separate pieces of Ω."}, {"q": "A ticket picks 6 of 49 numbers. The number of possible draws is:", "a": "C(49, 6) = 13 983 816", "w": ["49⁶", "49 × 6", "6!"], "why": "Choosing 6 of 49, order not counted (4k13)."}, {"q": "Two cards from one deck: P(both aces) = (4/52)(3/51). What is happening?", "a": "Multiplying along one path of a tree", "w": ["Adding over separate paths", "Turning a given chance around", "Multiplying chances of independent draws"], "why": "The branch-product technique: the second branch is a chance given the first."}, {"q": "A₁, …, Aₙ independent. The chance that at least one happens is:", "a": "1 − (1 − P(A₁))⋯(1 − P(Aₙ))", "w": ["P(A₁) + ⋯ + P(Aₙ)", "P(A₁)⋯P(Aₙ)", "1 − P(A₁)⋯P(Aₙ)"], "why": "The at-least-one technique: none happens is the product of the nots."}, {"q": "At least one six in 4 throws of a die has chance about:", "a": "0.518", "w": ["0.667", "0.482", "0.167"], "why": "1 − (5/6)⁴ = 671/1296."}, {"q": "The odds of A are:", "a": "P(A) / P(not A)", "w": ["P(A) / P(Ω)", "P(not A) / P(A)", "P(A) − P(not A)"], "why": "A chance of 1/4 is odds of 1/3."}, {"q": "Odds after seeing E = odds before × which ratio?", "a": "P(E | A) / P(E | not A)", "w": ["P(A | E) / P(not A | E)", "P(E) / P(A)", "P(A) / P(E)"], "why": "The odds-update technique (30l3)."}, {"q": "1 in 100 have a condition; the test flags 9 in 10 of them and 9 in 100 of the rest. A flagged person has it with chance about:", "a": "0.09", "w": ["0.9", "0.5", "0.01"], "why": "Odds 1/99 × 10 = 10/99, chance 10/109."}, {"q": "“The test finds 9 in 10 who have it, so a flagged person has it with chance 0.9.” What is wrong?", "a": "It swaps P(E | A) for P(A | E)", "w": ["It adds chances of events that overlap", "It treats dependent draws as independent", "Nothing: the two chances are equal"], "why": "A move to watch out for of 30l4; its accepted name is the base-rate fallacy."}, {"q": "“Red came up five times running, so black is due.” Why is this not allowed?", "a": "Separate spins are independent: black’s chance is unchanged", "w": ["Black’s chance falls after reds", "The spins are separate events, so their chances add", "Five reds make the wheel unfair"], "why": "P(black | five reds) = P(black)."}, {"q": "Two cards are dealt. Is P(first is an ace or second is an ace) = 4/52 + 4/52?", "a": "No: the two events overlap, when both are aces", "w": ["Yes, always", "Yes, because the cards are different", "No: it is (4/52)(4/51)"], "why": "Chances add only over separate events; the chance technique (30f1) subtracts the overlap."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30m"]=[{"q": "X has density f. P(X in A) is:", "a": "the total of f over A, ∫ over A of f", "w": ["f(A)", "the greatest value of f on A", "f at the middle of A"], "why": "The definition of a density (30m1)."}, {"q": "X has density f, g ≥ 0 sized. E g(X) equals:", "a": "∫ g(x) f(x) dx", "w": ["g(∫ x f(x) dx)", "∫ g(x) dx", "∫ f(g(x)) dx"], "why": "The density-average technique (30m1)."}, {"q": "Which licenses passing from step functions gₙ rising to g, in the density-average technique?", "a": "The rising-limit technique (30d1)", "w": ["The fenced-limit technique (30d3)", "The forgets-the-wait technique (30m2)", "The bell-series technique (30m3)"], "why": "gₙ ≥ 0 rise to g, on both sides."}, {"q": "X flat on [u, v]. Its average and spread are:", "a": "(u + v)/2 and (v − u)²/12", "w": ["(u + v)/2 and (v − u)²/4", "(v − u)/2 and (v − u)/12", "(u + v)/2 and (v − u)/√12"], "why": "From ∫ x/(v − u) and ∫ x²/(v − u)."}, {"q": "The exponential density of rate λ has average:", "a": "1/λ", "w": ["λ", "λ²", "ln 2/λ"], "why": "E X = 1!/λ (30m2)."}, {"q": "P(X > s + t | X > s) = P(X > t) for every s, t ≥ 0. What is this called on the page?", "a": "The forgets-the-wait technique", "w": ["The stretched-density technique", "The density-average technique", "The first-gap technique"], "why": "The exponential wait has no memory (30m2)."}, {"q": "A half-life of 8.02 days gives λ equal to:", "a": "ln 2 / 8.02 per day", "w": ["1/8.02 per day", "8.02 / ln 2 per day", "½ × 8.02 per day"], "why": "e^(−8.02λ) = ½."}, {"q": "Y = μ + σX with σ > 0, X with density f. Y has density:", "a": "(1/σ) f((y − μ)/σ)", "w": ["σ f(σy + μ)", "f((y − μ)/σ)", "(1/σ) f(σy + μ)"], "why": "The stretched-density technique (30m3)."}, {"q": "P(0 ≤ Z ≤ x) = (1/√(2π)) Σ (−1)ᵏ x^(2k+1)/(2ᵏ k!(2k + 1)). What does this?", "a": "The bell-series technique: exp as a sum, then term by term", "w": ["The bell-total technique alone", "The central limit technique", "The density-average technique"], "why": "30m3, from 22j3 and 23e3."}, {"q": "For the standard bell, P(|Z| ≤ 1) is about:", "a": "0.683", "w": ["0.5", "0.954", "0.341"], "why": "Twice 0.3413."}, {"q": "f = 3 on [0, ⅓]. “The chance of landing at 0.2 is 3.” What is wrong?", "a": "A height of a density is not a chance", "w": ["f is not a density", "The chance is ⅓", "The chance is 1"], "why": "A single value has chance 0 (15·stat); chances are areas."}, {"q": "Is E X² = (E X)² for X flat on [0, 1]?", "a": "No: 1/3 against 1/4", "w": ["Yes, always", "Yes, for flat densities", "No: 1/4 against 1/3"], "why": "The gap is Var X = 1/12."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30n"]=[{"q": "A walk of n independent steps, each with average 0 and spread width s, has spread width:", "a": "s√n", "w": ["ns", "s/√n", "s²n"], "why": "The root-n technique (30n1)."}, {"q": "Which licenses Var Sₙ = Var X₁ + ⋯ + Var Xₙ for a walk?", "a": "The independent-spreads-add technique (30g3)", "w": ["The average-adds technique (30g1)", "The spread-bound technique (30h1)", "The ruin-chance technique (30k4)"], "why": "The steps are independent."}, {"q": "100 tosses of a fair coin. The spread width of heads minus tails is:", "a": "10", "w": ["100", "50", "5"], "why": "√100 (30n1)."}, {"q": "The fair coin walk is back at 0 after 2n steps with chance:", "a": "C(2n, n)/4ⁿ, close to 1/√(πn)", "w": ["½", "1/(2n)", "C(2n, n)/2ⁿ"], "why": "The back-at-start technique (30n1)."}, {"q": "Steps of length h every τ seconds. D is:", "a": "h²/(2τ)", "w": ["h/τ", "h²/τ²", "2h²/τ"], "why": "The spread-in-time technique (30n2)."}, {"q": "The average square distance of such a walk after time t, in three directions, is:", "a": "6Dt", "w": ["2Dt", "3Dt", "6Dt²"], "why": "2Dt along each of three square directions (30n2)."}, {"q": "Which earlier page held x² = 2Dt in trust, and is paid here?", "a": "14·bio", "w": ["15·stat", "22·stat", "13·stat"], "why": "The spread-in-time technique earns it (30n2)."}, {"q": "The fair coin walk from k, stopped at 0 or N, takes on average:", "a": "k(N − k) steps", "w": ["N steps", "k/N steps", "N² steps"], "why": "The exit-time technique (30n3)."}, {"q": "Which shows that Sₙ² − n is a fair game in the exit-time proof?", "a": "Given the past, the next step averages 0 and its square is 1", "w": ["The ruin-chance technique", "The walk comes back with chance 1", "The central limit technique"], "why": "E[(S + X)² − (n + 1)] = S² − n."}, {"q": "Does the fair coin walk on a line come back to 0?", "a": "Yes, with chance 1, but the average time is endless", "w": ["Yes, within about √n steps on average", "No, its spread grows", "Only if it starts at 0 and n is even"], "why": "The comes-back technique (30n3)."}, {"q": "“Twice as far takes twice as long.” For spreading, how long does twice as far take?", "a": "Four times as long", "w": ["Twice as long", "√2 times as long", "The same time"], "why": "t = x²/(2D)."}, {"q": "The walk is at +20. Is its next step more likely to go down?", "a": "No: each step averages 0, wherever the walk is", "w": ["Yes: it is pulled back to 0", "Yes, with chance 20/21", "Only after a long run up"], "why": "The steps are independent of the past."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30o"]=[{"q": "A rare-arrival stream of rate λ: the count in a stretch of length t is:", "a": "a rare count of average λt", "w": ["λt exactly", "a flat count on 0 to λt", "a bell of average λt"], "why": "The definition (30o1)."}, {"q": "In a rare-arrival stream of rate λ, P(no arrival in the next t) is:", "a": "e^(−λt)", "w": ["1 − λt", "λe^(−λt)", "e^(−t/λ)"], "why": "The first-gap technique (30o1)."}, {"q": "Calls come at 12 an hour as a rare-arrival stream. The average wait for the next call from any moment is:", "a": "5 minutes", "w": ["2.5 minutes", "12 minutes", "10 minutes"], "why": "1/λ = 1/12 hour."}, {"q": "Buses come as a rare-arrival stream, every 10 minutes on average. “A rider who arrives at random waits 5.” What is wrong?", "a": "The wait from any moment averages the whole 10 minutes", "w": ["The wait is 20 minutes", "Buses never bunch", "Nothing: half the gap is right"], "why": "The first-gap technique; its accepted name is the waiting-time paradox."}, {"q": "S and T independent exponentials of rates λ and μ. The first of them is exponential of rate:", "a": "λ + μ", "w": ["λμ", "λμ/(λ + μ)", "the larger of λ and μ"], "why": "The first-of-two technique (30o2)."}, {"q": "S and T as above. S comes first with chance:", "a": "λ/(λ + μ)", "w": ["μ/(λ + μ)", "½", "λ/μ"], "why": "The first-of-two technique (30o2)."}, {"q": "Which licenses joining two rare-arrival streams into one of rate λ + μ?", "a": "The pages-add technique (22·stat4)", "w": ["The rare-events technique (22j2)", "The two-state technique (30o3)", "The steady-line technique (30o4)"], "why": "Independent rare counts add to a rare count."}, {"q": "A two-state chain leaves state 1 at rate a and state 2 at rate β. In the long run it is in state 1 with chance:", "a": "β/(α + β)", "w": ["α/(α + β)", "α/b", "½"], "why": "The two-state technique (30o3)."}, {"q": "Which licenses solving p′ = −(α + β)(p − β/(α + β)) in the two-state technique?", "a": "The shift-to-rest technique (24h1)", "w": ["The forgets-the-wait technique (30m2)", "The whole-chance technique (30f3)", "The endless-ratio-sum technique (15i3)"], "why": "y′ = k(y − A) has the one solution A + (y₀ − A)e^(kt)."}, {"q": "A line at one window: arrivals at rate λ, service at rate μ, ρ = λ/μ < 1. The average number in the system is:", "a": "ρ/(1 − ρ)", "w": ["ρ", "1/(1 − ρ)", "λ − μ"], "why": "The steady-line technique (30o4)."}, {"q": "μpₙ₊₁ = λpₙ for every n. What is it on the page?", "a": "Flow up across each cut equals flow down", "w": ["The rare count", "The first-gap technique", "The forgets-the-wait technique"], "why": "From the steady equations (30o4)."}, {"q": "“Arrivals at 50 an hour and service at 50 an hour balance, so the line stays short.” What is wrong?", "a": "With ρ = 1 there are no steady chances: the line grows without bound", "w": ["The line is exactly 1 on average", "The window is idle half the time", "Nothing: the rates balance"], "why": "pₙ = p₀ for all n cannot add to 1."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30p"]=[{"q": "In a chance grid P (as on 30p), what does every column add to?", "a": "1", "w": ["0", "The number of states", "The settled chance of that state"], "why": "Column j lists the chances of where the chain goes from state j (30p1)."}, {"q": "The chance list after n steps of a chain that forgets its past is:", "a": "Pⁿx₀", "w": ["nPx₀", "P x₀ⁿ", "x₀ + nP"], "why": "The chance-grid technique (30p1), one step at a time by the whole-chance technique."}, {"q": "Which licenses x₁ = P x₀ for a chain that forgets its past?", "a": "The whole-chance technique (30f3), with given chances P_ij", "w": ["The turn-around technique (30f3)", "The average-adds technique (30g1)", "The stretch-test technique (27f)"], "why": "The states at step 0 split the chances into separate cases (30p1)."}, {"q": "Wet days: after wet, wet with chance 0.7; after dry, wet with chance 0.4. Today is wet. The chance of wet in two days is:", "a": "0.61", "w": ["0.49", "0.7", "0.57"], "why": "0.7 · 0.7 + 0.3 · 0.4: both roads count (30p1, 30p4)."}, {"q": "A settled list π of a chance grid P is:", "a": "A chance list with Pπ = π", "w": ["Any vector with Pπ = π", "The first column of P", "The list of row sums of P"], "why": "Only stretched by P, by 1, and its entries add to 1 (30p2)."}, {"q": "The shrinking-differences technique says |Pd| ≤ (1 − m)|d| when:", "a": "The entries of d add to 0", "w": ["d is a chance list", "d is settled", "Every entry of d is above 0"], "why": "Differences of two chance lists add to 0 (30p2)."}, {"q": "For a chance grid with every entry above 0, the one-rank technique gives:", "a": "One settled list, reached from every start", "w": ["Two settled lists", "A settled list only from the settled start", "Chances that flip for ever"], "why": "The lists crowd and so settle (22c), and a second settled list would have to be the first (30p2)."}, {"q": "Two states: leave state 1 with chance α, state 2 with chance β. The settled list is:", "a": "(β, α)/(α + β)", "w": ["(α, β)/(α + β)", "(1 − α, 1 − β)", "(½, ½)"], "why": "P(β, α) = (β, α); the fading-start technique (30p3). Balance: π₁α = π₂β."}, {"q": "For two states, the start fades by which factor each step?", "a": "1 − α − β", "w": ["α + β", "ab", "1 − αβ"], "why": "1 − α − b is the second stretch, by the middle-sum technique (27l); the fading-start technique (30p3)."}, {"q": "The grid with columns (0, 1) and (1, 0), started at (1, 0):", "a": "Never settles, yet the share of time in each state heads to ½", "w": ["Settles at (½, ½)", "Settles at (1, 0)", "Has no settled list"], "why": "It flips for ever; m = 0. The share-of-time technique needs only the averages of the chance lists to head to π (30p.4.2)."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30q"]=[{"q": "The spread width of the average of n independent readings of width σ is:", "a": "σ/√n", "w": ["σ/n", "σ√n", "σ"], "why": "The sample-average technique (30q1): Var X̄ = σ²/n."}, {"q": "To halve the width of a sample average you need:", "a": "Four times as many readings", "w": ["Twice as many readings", "Half as many readings", "The square root as many readings"], "why": "The width is σ/√n (30q1)."}, {"q": "Which licenses Var(X₁ + ⋯ + Xₙ) = nσ² for independent readings?", "a": "The independent-spreads-add technique (30g3)", "w": ["The average-adds technique (30g1)", "The spread-bound technique (30h1)", "The central limit technique (30j3)"], "why": "Independent parts have co-spread 0, so their spreads add (30q1)."}, {"q": "Why divide by n − 1 in the sample spread S²?", "a": "So that E S² = σ²", "w": ["So that S² is never 0", "So that S = σ exactly", "Because one reading is always wrong"], "why": "The sample-spread technique (30q2): with n in the bottom the average is (n − 1)σ²/n."}, {"q": "Which licenses Σ(Xᵢ − μ)² = Σ(Xᵢ − X̄)² + n(X̄ − μ)²?", "a": "The squared-misses technique (8·stat)", "w": ["The sample-average technique (30q1)", "The independent-spreads-add technique (30g3)", "The bell-series technique (30m3)"], "why": "With c = μ (30q2)."}, {"q": "The 95% interval from the bell, with σ known, is:", "a": "X̄ ± 1.96σ/√n", "w": ["X̄ ± 1.96σ", "X̄ ± 1.96σ/n", "μ ± 1.96σ/√n"], "why": "The bell-cover technique (30q3), from the central limit technique."}, {"q": "After the sample is drawn, a 95% interval 5.06 to 6.19 m:", "a": "Either covers μ or does not; 95% describes the method", "w": ["Covers μ with chance 0.95", "Holds 95% of the readings", "Holds μ̂ with chance 0.95"], "why": "μ is fixed; the chance belongs to the interval before the sample (30q3, 30q5)."}, {"q": "With σ unknown and 8 bell-shaped readings, the 95% interval uses:", "a": "X̄ ± 2.365 S/√8", "w": ["X̄ ± 1.96 S/√8", "X̄ ± 2.365 S/8", "X̄ ± 1.96 σ/√7"], "why": "The small-sample-cover technique (30q4), t for 7 degrees, from the trusted t pattern."}, {"q": "As the sample grows, the table's t value heads to:", "a": "1.96", "w": ["0", "12.706", "2.365"], "why": "S settles at σ (30h2), so the bell's value returns (30q4)."}, {"q": "What on 30q is held in trust?", "a": "That T = (X̄ − μ)/(S/√n) has a chance pattern depending only on n − 1, for bell-shaped readings", "w": ["That E S² = σ²", "That Var X̄ = σ²/n", "That the bell's area from −1.96 to 1.96 is 0.950"], "why": "Its proof waits much higher up the ladder; the other three are proved (30q2, 30q1, 30m3)."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30r"]=[{"q": "The likelihood L(θ) is:", "a": "The chance of the record, read as a function of the knob θ", "w": ["The chance that θ is right", "The chance of θ given the record", "The average of the readings"], "why": "30r1, as on 14·stat."}, {"q": "Why do L and ℓ = ln L have the same tops?", "a": "ln is rising", "w": ["ln of a product is a sum", "ln is continuous", "ln 1 = 0"], "why": "The log-likelihood technique (30r1): L(θ₁) < L(θ₂) exactly when ℓ(θ₁) < ℓ(θ₂)."}, {"q": "For independent readings, the likelihood of the whole record is:", "a": "The product of the chances of the readings", "w": ["The sum of their chances", "The largest of their chances", "The average of their chances"], "why": "Independence (30f2); 30r5's second move to watch out for adds them."}, {"q": "Counts of rare events k₁, …, kₙ with k̄ > 0: the best guess of λ is:", "a": "k̄", "w": ["1/k̄", "k̄²", "The largest count"], "why": "The rare-guess technique (30r2)."}, {"q": "Waits x₁, …, xₙ between arrivals of rate λ: the best guess of λ is:", "a": "1/x̄", "w": ["x̄", "ln x̄", "x̄/n"], "why": "The gap-guess technique (30r2)."}, {"q": "Which licenses: the best guess of e^(−λ) is e^(−λ̂)?", "a": "The same-best technique (30r1)", "w": ["The log-likelihood technique (30r1)", "The rare-guess technique (30r2)", "The top-bend technique (30r4)"], "why": "g(λ) = e^(−λ) is one-to-one on λ ≥ 0."}, {"q": "For bell-shaped readings, the best guess of σ² is:", "a": "Σ(xᵢ − x̄)²/n", "w": ["Σ(xᵢ − x̄)²/(n − 1)", "Σxᵢ²/n", "(max − min)²/4"], "why": "The bell-guess technique (30r3); n in the bottom, a little short on average (30q2)."}, {"q": "Six months, no eruptions: the best guess of the monthly rate is 0, where ℓ′ is:", "a": "−6", "w": ["0", "6", "Not defined"], "why": "ℓ(λ) = −6λ falls all the way; the top sits at an end (14·stat's end-guess)."}, {"q": "For a share k/n, 1/(−ℓ″(p̂)) equals:", "a": "p̂(1 − p̂)/n", "w": ["p̂/n", "n/(p̂(1 − p̂))", "p̂(1 − p̂)"], "why": "The top-bend technique (30r4): the sample-average spread with p̂ for p."}, {"q": "Readings spread evenly over [0, θ]: 3.1, 7.4, 5.2. The best guess of θ is:", "a": "7.4", "w": ["10.47", "5.23", "Where ℓ′ = 0"], "why": "L = θ⁻³ for θ ≥ 7.4 and 0 below; its top is at the edge, slope not 0 (30r.4.2)."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30s"]=[{"q": "The surprise chance of a seen test number z is:", "a": "The chance, if the claim is true, of a test number at least as far from 0", "w": ["The chance that the claim is true", "The chance that the claim is false", "The chance of exactly z"], "why": "30s1 (accepted name p-value)."}, {"q": "A fair coin tossed 10 000 times lands heads 5067 times. z is:", "a": "1.34", "w": ["0.67", "67", "0.0067"], "why": "(5067 − 5000)/50, with width √(10 000 · ¼) = 50 (30s1)."}, {"q": "Surprise 0.18 > 0.05 means:", "a": "The record does not reject the claim", "w": ["The claim is proved", "The claim has chance 0.18", "The claim has chance 0.82"], "why": "Not rejecting is not proving; the test may lack power (30s1, 30s5)."}, {"q": "Rejecting when |Z| ≥ 1.96 rejects a true claim with chance heading to:", "a": "0.05", "w": ["0.95", "0.025", "1.96"], "why": "The bell-test technique (30s1)."}, {"q": "An error of the second kind is:", "a": "Keeping a claim that is false", "w": ["Rejecting a claim that is true", "Testing the wrong claim", "Using the bell for a small sample"], "why": "30s3; its chance is one less the power."}, {"q": "To keep power fixed while halving the difference to be caught, the sample must grow by a factor of:", "a": "4", "w": ["2", "√2", "8"], "why": "d = (p − p₀)√n/√(p₀(1 − p₀)) (30s3, the test-power technique)."}, {"q": "Twenty true claims, each tested at 0.05. The chance at least one is rejected is about:", "a": "0.64", "w": ["0.05", "0.95", "1"], "why": "1 − 0.95²⁰ (30s3, 30s5)."}, {"q": "With two cells, X² equals:", "a": "Z², the bell test number squared", "w": ["2Z", "|Z|", "Z/2"], "why": "The two-cell technique (30s4); so 3.841 ≈ 1.96²."}, {"q": "The first pea counts, 5474 round and 1850 wrinkled, against 3 : 1, give X² ≈:", "a": "0.263", "w": ["19", "0.513", "3.841"], "why": "19²/5493 + 19²/1831 (30s4)."}, {"q": "In a two-way table tested for independence, a cell's expected count is:", "a": "Row total × column total / n", "w": ["Row total + column total", "n / number of cells", "Row total × column total"], "why": "Independence (30f2) with the record's shares for the chances (30s4)."}, {"q": "A 2 × 2 table tested for independence has how many degrees?", "a": "1", "w": ["2", "3", "4"], "why": "(r − 1)(k − 1) = 1: the totals fix the rest (30s4, held in trust in general)."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30t"]=[{"q": "The likelihood ratio of data x, claim H₀ against rival H₁, is:", "a": "Λ(x) = f₁(x)/f₀(x)", "w": ["f₀(x) − f₁(x)", "f₁(x) + f₀(x)", "P(H₁ | x)"], "why": "How many times more likely the rival makes the data than the claim (30t1)."}, {"q": "If H₀ is true, the chance that Λ reaches k is at most:", "a": "1/k", "w": ["k", "1/k²", "0.05 always"], "why": "The ratio-bound technique: E₀[Λ] ≤ 1, then the stray-bound technique."}, {"q": "Which licenses P₀(Λ ≥ k) ≤ E₀[Λ]/k?", "a": "The stray-bound technique (30h)", "w": ["The spread-bound technique (30h)", "The turn-around technique (30f)", "The central limit technique (30j)"], "why": "Λ ≥ 0, so the stray bound applies; the spread bound needs a spread, and the others give no bound on a tail."}, {"q": "For independent readings, the likelihood ratio of the whole record is:", "a": "the product of one ratio per reading", "w": ["the sum of one ratio per reading", "the ratio of the averages", "the largest single ratio"], "why": "Each story’s chance of the record is a product (30f), so their ratio is too."}, {"q": "The best-test technique says that rejecting H₀ when Λ is large:", "a": "has the greatest power among tests whose level is at most its own", "w": ["has the smallest level of all tests", "is never wrong", "gives the chance that H₁ is true"], "why": "Fix the chance of an error of the first kind; nothing with that chance or less catches more (30t2)."}, {"q": "The first line of the best-test proof, (φ* − φ)(f₁ − kf₀) ≥ 0, holds because:", "a": "where f₁ > kf₀, φ* = 1; where f₁ < kf₀, φ* = 0", "w": ["φ and φ* are both chances", "f₁ is always bigger than kf₀", "k is chosen as 0"], "why": "Check each side of k; at equality the factor is 0."}, {"q": "Bell readings with known spread, H₀: μ = 200 against H₁: μ = 210. The best test rejects when:", "a": "x̄ > c, with c fixed by the level alone", "w": ["x̄ < c", "|x̄ − 205| is large", "x̄ > 210"], "why": "log Λ climbs with x̄ when μ₁ > μ₀, and c never uses 210: best against every μ₁ above 200."}, {"q": "A summary T is a full summary when, given T = t, the chance of the data:", "a": "is the same for every θ", "w": ["is 1", "is greatest at the best guess", "does not depend on t"], "why": "The definition in 30t3: the rest of the data is a draw θ has no say in."}, {"q": "The summary-factor technique: T is a full summary exactly when f(x; θ) is:", "a": "g(T(x), θ) · h(x)", "w": ["g(θ) + h(x)", "g(x) · h(θ) for any split", "the same for every x"], "why": "θ meets the data only through T (30t3)."}, {"q": "For readings landing evenly in [0, θ], a full summary is:", "a": "the largest reading", "w": ["the average", "the smallest reading", "the number of readings"], "why": "f = θ⁻ⁿ when θ ≥ the largest reading, 0 otherwise."}, {"q": "Λ = 20 for the rival. The chance the rival is true is:", "a": "not fixed by Λ alone: it needs odds held before the data", "w": ["20/21", "0.95", "1 − 1/20"], "why": "The odds-update technique (30l) multiplies the odds before by Λ; 20/21 assumes even odds before."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30u"]=[{"q": "The belief after the data is:", "a": "the belief before times the likelihood, scaled to total 1", "w": ["the belief before plus the likelihood", "the likelihood alone", "the belief before, unchanged by data"], "why": "The belief-update technique (30u1), from the turn-around and whole-chance techniques."}, {"q": "Which licenses P(X = x) = Σ f(x | θᵢ)π(θᵢ) in the belief-update proof?", "a": "The whole-chance technique (30f)", "w": ["The independent technique (30f)", "The average-adds technique (30g)", "The chance technique (30f)"], "why": "The settings θᵢ split the space into separate events of positive chance; the others do not sum given chances."}, {"q": "Updating on x, then on y (independent given θ), gives:", "a": "the same belief as updating on x and y at once", "w": ["a belief twice as sure as it should be", "a different answer depending on the order", "the belief before again"], "why": "Today’s belief after is tomorrow’s belief before (30u1)."}, {"q": "A belief of 0 on a setting before the data becomes, after any data:", "a": "0", "w": ["the likelihood of that setting", "½", "whatever the data favour"], "why": "Zero times any likelihood is zero."}, {"q": "beta(α, β) belief about a share; k successes in n tries. The belief after is:", "a": "beta(α + k, β + n − k)", "w": ["beta(α + n, β + k)", "beta(k, n − k)", "beta(a k, β(n − k))"], "why": "The shape-keeping technique: successes add to α, failures to β."}, {"q": "The average of beta(α, β) is:", "a": "α/(α + β)", "w": ["(α − 1)/(α + β − 2)", "β/(α + β)", "ab/(α + β)²"], "why": "B(α + 1, β)/B(α, β) = α/(α + β), by the parts technique (16e)."}, {"q": "Flat belief before; n sunrises in n days. The chance of one more is:", "a": "(n + 1)/(n + 2)", "w": ["n/(n + 1)", "1", "1/2"], "why": "The average of beta(n + 1, 1) (30u2)."}, {"q": "Bell belief of spread τ², n bell readings of spread σ². After the data, 1/S² is:", "a": "1/τ² + n/σ²", "w": ["τ² + σ²/n", "1/τ² · n/σ²", "n/σ² only"], "why": "The bell-update technique: sureness adds."}, {"q": "With a flat belief before, the 95% belief interval for a bell average is:", "a": "x̄ ± 1.96σ/√n, the same numbers as 30q’s interval", "w": ["wider than 30q’s interval", "narrower than 30q’s interval", "not defined"], "why": "As τ grows without bound, the belief after heads to the bell of average x̄ and spread σ²/n."}, {"q": "After the data, a 95% interval from 30q (the bell-cover technique):", "a": "covers μ or does not; 95% described the method", "w": ["holds μ with chance 0.95", "holds μ with chance 0.05", "holds x̄ with chance 0.95"], "why": "μ is not a chance variable in 30q; the chance belonged to the interval before sampling."}, {"q": "θ flat on [0, 1]. Then P(θ² ≤ ¼) is:", "a": "½", "w": ["¼", "1/16", "1"], "why": "θ² ≤ ¼ exactly when θ ≤ ½: a flat belief is flat in only one way of measuring."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30v"]=[{"q": "An observational study differs from an experiment because:", "a": "the researcher records what people chose, and decides nothing", "w": ["it has fewer people", "it uses no numbers", "it is always wrong"], "why": "In an experiment the researcher decides who gets what (30v1)."}, {"q": "Which licenses: a group’s overall rate is Σ (rate in part i) × (share in part i)?", "a": "The whole-chance technique (30f)", "w": ["The independent technique (30f)", "The average-adds technique (30g)", "The turn-around technique (30f)"], "why": "The parts split the group; this is the mixed-rate technique’s first line. The others do not split by parts."}, {"q": "Berkeley 1973, six departments: women admitted at a higher rate in four, lower overall, because:", "a": "women applied mostly to departments that admitted few", "w": ["the counts were wrong", "women applied in fewer departments", "the rates were rounded"], "why": "The mixed-rate technique: the shares decide the overall comparison."}, {"q": "Each member is picked with chance π(X). The picked average heads to:", "a": "E X + Cov(X, π(X))/E[π(X)]", "w": ["E X", "E X · E π", "E X − Cov(X, π)"], "why": "The picked-lean technique (30v2)."}, {"q": "A leaning sample of 2.4 million answers:", "a": "settles on the leaning value, not on E X", "w": ["cannot be far off", "is fair because it is large", "settles on E X slowly"], "why": "Averages settle on E[Xπ]/E[π]; size does not cure a lean."}, {"q": "Trips of 2 h and 6 h equally common; a bank counter meets anglers with chance ∝ time. Their average heads to:", "a": "5 h", "w": ["4 h", "6 h", "3 h"], "why": "E[X²]/E X = 20/4 = 5 (30v2)."}, {"q": "Under a fair draw of the treated group, the difference of group averages has average:", "a": "τ, the average effect over all units", "w": ["0 always", "the treated average", "τ only if the groups are large"], "why": "The fair-split technique: each unit is treated with chance m/N (6·stat)."}, {"q": "A trait nobody measured, under a fair draw, differs between the groups by:", "a": "0 on average", "w": ["0 exactly", "an amount that cannot be known even on average", "the treatment effect"], "why": "A trait is a pair of futures the treatment does not change (30v3)."}, {"q": "Blinding means:", "a": "neither those treated nor those judging know who had what", "w": ["the treatment is given at random", "a look-alike treatment is given", "the sample is picked fairly"], "why": "So hopes cannot tilt a diagnosis (30v3)."}, {"q": "Pairs alike in soil: the spread of the difference within a pair is:", "a": "Var y + Var z − 2 Cov(y, z)", "w": ["Var y + Var z", "Var y − Var z", "2 Cov(y, z)"], "why": "The spread-of-a-sum technique (30g); large co-spread makes it small."}, {"q": "R independent simulation runs estimate a chance p. Then P(|p̂ − p| ≥ e) is at most:", "a": "1/(4Re²)", "w": ["1/(Re)", "e/R", "1/(4R)"], "why": "The run-count technique: spread at most 1/(4R), then the spread-bound technique."}, {"q": "To halve the doubt in a simulated chance, the runs must be:", "a": "multiplied by 4", "w": ["doubled", "halved", "multiplied by 16"], "why": "The spread width is √(p(1 − p)/R)."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["30w"]=[{"q": "Which axiom stands under every line that writes one name where an equal one stood?", "a": "the swap axiom", "w": ["the self-sameness axiom", "the same-members axiom", "the axiom of choice"], "why": "0b: a statement about x holds just as well with b's name where x's stood, once x = b."}, {"q": "From which rung on does the ladder stop naming the swap axiom?", "a": "rung 14", "w": ["rung 1", "rung 22", "rung 30"], "why": "It is under every line by then, so naming it tells you nothing about which line you are on."}, {"q": "In the series, what does a check end at when it succeeds?", "a": "a = a", "w": ["a = b for two different numbers", "a line with no reason", "an axiom"], "why": "Self-sameness is the yardstick every check is laid against."}, {"q": "A check ends at 1 ≤ 0. What has happened?", "a": "the case is refused: the check failed", "w": ["the swap axiom failed", "the case is proved", "nothing; keep going"], "why": "Self-sameness and the order of the numbers refuse such a line."}, {"q": "What does a move that iterates itself do?", "a": "runs the same move again on its own output", "w": ["changes a little each rung", "proves its own axiom", "replaces an axiom"], "why": "9·cb4: g, then g of that, then g of that."}, {"q": "Which move does 30a's outer size share with 8c, 15's sums and 22a's climb?", "a": "fencing a number between lists that close in", "w": ["the chain", "sharing slack as ε/2ⁿ", "the turn-around"], "why": "The least upper bound move, unchanged across rungs."}, {"q": "Are the eight anexact, yet rigorous principles proved?", "a": "no; they are guesses from things, supported by their recurrence", "w": ["yes, on rung 30", "yes, by the swap axiom", "no; they are axioms"], "why": "Recurrence is evidence with a count and an exception rate, not a proof."}, {"q": "What is induction under the case with unpredictable variation?", "a": "statistics: a guess about a crowd of cases, with its count and exception rate", "w": ["science: a law from cases that behave alike", "deduction over the arrangement", "mathematics over the series"], "why": "Its short name is induction under the large case."}, {"q": "Which preposition names what goes into a guess?", "a": "under", "w": ["over", "into", "from"], "why": "Under the small case, under the large case."}, {"q": "Which kind of guessing is induction over the series?", "a": "mathematics", "w": ["statistics", "science", "abduction"], "why": "From a case to the next, for every case at once (4c)."}, {"q": "A driver slows on a wet road at dusk. Which kind of guessing?", "a": "induction into action", "w": ["induction into the plan", "induction over the arrangement", "induction under the large case"], "why": "What comes out is an act: transduction."}];
